      id: 'stack-queue', after: 'lists', chapter: 'data', title: 'ستاک و ڕیز (Stack/Queue)', minutes: 7, level: 3,
      body: `
        <p>دوو ڕێگای گرنگی بەکارهێنانی لیست:</p>
        <ul>
          <li><b>ستاک (Stack)</b>: «کۆتا هاتوو، یەکەم دەرچوو» (LIFO) وەک کۆمەڵێک پەرداخ. <code>.زیادبکە(x)</code> دەیخاتە سەرەوە، <code>.لابەرە()</code> سەرەوە دەهێنێتەوە.</li>
          <li><b>ڕیز (Queue)</b>: «یەکەم هاتوو، یەکەم دەرچوو» (FIFO) وەک ڕیزی ناندا. <code>.زیادبکە(x)</code> بۆ کۆتایی، <code>.یەکەمیلابەرە()</code> یەکەم دەهێنێتەوە.</li>
        </ul>
        <pre class="ex">نەگۆڕ ل = [١، ٢، ٣]
چاپ(ل.لابەرە())           // 3  (کۆتا)
چاپ(ل.یەکەمیلابەرە())     // 1  (یەکەم)
چاپ(ل)                    // [2]</pre>`,
      task: 'ستاکێک بکە و <code>١، ٢، ٣</code> زیاد بکە، پاشان بە <code>هەتا</code> هەمووی لابەرە و چاپ بکە (<code>٣، ٢، ١</code>). پاشان هەمان شت بۆ <b>ڕیز</b> بکە (<code>١، ٢، ٣</code>).',
      starter: '// ١. ستاک: زیادبکە ١، ٢، ٣ ← هەتا درێژی > ٠ { چاپ(.لابەرە()) }\n// ٢. ڕیز: زیادبکە ١، ٢، ٣ ← هەتا درێژی > ٠ { چاپ(.یەکەمیلابەرە()) }\n',
