      hint: 'کار بەشیگەورە(a، b) {\n  ئەگەر b == ٠ { گەڕێنەوە a }\n  گەڕێنەوە بەشیگەورە(b، a % b)\n}',
      solution: 'کار بەشیگەورە(a، b) {\n  ئەگەر b == ٠ { گەڕێنەوە a }\n  گەڕێنەوە بەشیگەورە(b، a % b)\n}\n\nچاپ(بەشیگەورە(٤٨، ١٨))\nچاپ(بەشیگەورە(١٧، ٥))\nچاپ(بەشیگەورە(١٠٠، ٧٥))\n',
      expect: ['6', '1', '25'],
      mustUse: ['کار', 'ئەگەر', 'گەڕێنەوە'],
      recap: ['ئیوکلید: <code>GCD(a, b) = GCD(b, a % b)</code>، و <code>GCD(a, ٠) = a</code>.', 'هەموو Recursionـێک حاڵەتی کۆتایی (<code>b == ٠</code>) و بانگکردنی بچووکتر پێویستە.', 'یەکێک لە کۆنترین ئەلگۆریتمەکانی مێژوو، هێشتا بەکاردێت!'],
