        <p>ژمارەکانی فیبۆناچی: هەر ژمارەیەک کۆی <b>دوو ژمارەی پێشوو</b>ـیەتی: <code>٠، ١، ١، ٢، ٣، ٥، ٨، ١٣...</code> پێشتر بە Recursion نووسیتمان، بەڵام ئەو ڕێگایە بۆ ژمارەی گەورە <b>زۆر هێواش</b>ە (هەمان ژمارە دووبارە دەژمێرێت).</p>
