      body: "<p>ڕیزی <code>i</code>ی هەرەمێک (ژمارە لە ١ دەست پێدەکات) لە ڕیزی ٤ ڕیزدا:</p>\n<ul>\n<li><code>ڕیزەکان - i</code> ناتوانراو (<b>.</b>) لە چەپ</li>\n<li><code>٢ * i - ١</code> ئەستێرە (<b>*</b>) لە ناوەڕاست</li>\n</ul>\n<pre class=\"ex\">...*       ← ڕیزی ١: ٣ نقتە، ١ ئەستێرە\n..***      ← ڕیزی ٢: ٢ نقتە، ٣ ئەستێرە\n.*****\n*******</pre>\n<p>لە جیاتی بۆشایی نقتە (<code>.</code>) بەکاردێنین، بۆ ئەوەی بتوانین ڕێکخستنەکە ببینین و بپشکنین. دوو بازنەی ناو بازنە: یەکێک بۆ نقتەکان و یەکێک بۆ ئەستێرەکان.</p>",
