      body: "<p>مەسەلەی دووەمی <b>Project Euler</b>: کۆی هەموو ژمارە <b>جووتەکانی</b> فیبۆناچی کە لە <b>چوار ملیۆن</b> زیاتر نین. (فیبۆناچی لە <code>١، ٢</code> دەست پێدەکات: ١، ٢، ٣، ٥، ٨، ١٣، ٢١، ٣٤...)</p>\n<p>پێویست بە لیست نییە: تەنها دوو گۆڕاو (<code>a</code> و <code>b</code>) بۆ دوو ژمارەی پێشوو بەکاربهێنە، و <code>هەتا a <= ٤٠٠٠٠٠٠</code>. هەر جارێک: ئەگەر <code>a</code> جووت بوو، بیخە کۆکەرەوە؛ پاشان <code>(a, b) = (b, a + b)</code> (گۆڕاوێکی کاتی بەکاربهێنە).</p>",
