      id: "zip-lists", after: "errors", chapter: "dataproc", title: "یەکخستنی دوو لیست (Zip)", minutes: 7, level: 2,
      body: "<p>هەندێک جار داتا لە دوو لیستی <b>جیا</b>دایە (ناوەکان و نمرەکان). بۆ یەکخستنیان، <code>.نەخشە</code> ئیندێکسی ئەندامیش دەدات (پارامەتەری دووەم)، و بە ئەو ئیندێکسە لە لیستەکەی تر ئەندامی هاوشێوە وەردەگریت:</p>\n<pre class=\"ex\">نەگۆڕ ناو = [\"ا\"، \"ب\"]\nنەگۆڕ تەمەن = [٢٠، ٣٠]\nنەگۆڕ ک = ناو.نەخشە((ن، i) => ({ ناو: ن، تەمەن: تەمەن[i] }))\n// [{ ناو: \"ا\", تەمەن: 20 }, { ناو: \"ب\", تەمەن: 30 }]</pre>\n<p>⚠️ ئۆبجێکت لە دوای <code>=></code> دەبێت لە <b>کەوانەدا</b> بێت: <code>=> ({ ... })</code>، ئەگینا <code>{</code> وەک بلۆکی کۆد دەخوێنرێتەوە.</p>",
      task: "ناوەکان و نمرەکان بکە بە لیستی ئۆبجێکت (<code>.نەخشە</code> بە ئیندێکس)، پاشان هەر یەکێک بنووسە بەم شێوەیە: <code>ناو: نمرە</code>.",
      starter: "نەگۆڕ ناوەکان = [\"ئارام\"، \"شیرین\"، \"ڕێبین\"]\nنەگۆڕ نمرەکان = [٧٢، ٩٥، ٨٨]\n// نەگۆڕ ل = ناوەکان.نەخشە((ن، i) => ({ ناو: ن، نمرە: نمرەکان[i] }))\n// بۆ هەر ق لە ل: چاپ(ق.ناو + \": \" + ق.نمرە)\n",
