      id: "sine-wave", after: "turtlestar", chapter: "draw", title: "شەپۆلی سینۆس", minutes: 9, level: 3,
      body: "<p>شەپۆلێک بکێشە بە <b>هێڵی کورت</b> لە نێوان خاڵە لەسەر یەک. بۆ هەر <code>x</code> (٠، ٥، ١٠...) ئەوپەڕی <code>y</code> بە <code>سینۆس</code> دیاری دەکرێت: <code>y = ناوەند - بەرزی * سینۆس(x / درێژی)</code>.</p>\n<pre class=\"ex\">بۆ i لە ٠ تا ٥٩ {\n  نەگۆڕ x١ = i * ٥\n  نەگۆڕ x٢ = (i + ١) * ٥\n  هێڵ(x١، y(x١)، x٢، y(x٢))    // لە خاڵێکەوە بۆ خاڵی دواتر\n}</pre>\n<p>لێرە <code>y(x)</code> کارێکە بۆ ئەوەی هەمان فۆرمووڵە دووبارە نەکەیتەوە. <code>- سینۆس</code> وا دەکات شەپۆلەکە لە سەرەوە دەست پێبکات (چونکە y بەرەو خوارەوە زیاد دەکات).</p>",
