      body: "<p>گرادیەنت (Gradient) واتە ڕەنگێک کە <b>هێواش هێواش دەگۆڕێت</b>. بە <b>ڕێزە ستوونی</b> کە هەر یەکە ڕەنگێکی کەمێک جیاواز: <code>ڕەنگی(سوور، سەوز، شین)</code> بەکاربهێنە و یەکێک لە ژمارەکان بەپێی <code>i</code> بگۆڕە:</p>\n<pre class=\"ex\">بۆ i لە ٠ تا ١٩ {\n  ڕەنگبکە(ڕەنگی(i * ١٢، ٠، ٢٥٥ - i * ١٢))   // لە شینەوە بۆ سوور\n  لاکێش(i * ١٥، ٠، ١٥، ١٠٠)\n}</pre>\n<p>ژمارەکانی <code>ڕەنگی</code> لە <code>٠</code> هەتا <code>٢٥٥</code> ن. هەر ڕێزێک <b>١٥ پیکسڵ</b> پانە (٢٠ × ١٥ = ٣٠٠).</p>",
