      task: 'بازنەیەک بکێشە کە <b>خۆی بەرەو ڕاست بجووڵێت</b>: <code>x</code> لە هەر فریمێکدا <code>٣</code> زیاد بکە. بە <code>یاریبکە</code> بیکە.',
      starter: 'قەبارە(٣٠٠، ١٦٠)\nگۆڕاو x = ٣٠\n// یاریبکە(() => {\n//   پاشبنەمابکە("ڕەش")\n//   ڕەنگبکە("زەرد")\n//   بازنە(x، ٨٠، ٢٠)\n//   x += ٣\n// })\n',
      hint: 'یاریبکە(() => {\n  پاشبنەمابکە("ڕەش")\n  ڕەنگبکە("زەرد")\n  بازنە(x، ٨٠، ٢٠)\n  x += ٣\n})',
      solution: 'قەبارە(٣٠٠، ١٦٠)\nگۆڕاو x = ٣٠\nیاریبکە(() => {\n  پاشبنەمابکە("ڕەش")\n  ڕەنگبکە("زەرد")\n  بازنە(x، ٨٠، ٢٠)\n  x += ٣\n})\n',
      game: true, simulate: [{ n: 30 }],
      verifyGame: (frames) => {
        const xs = firstOf(frames, 'circle', 1);
        if (xs[0] === null) return 'هیچ بازنەیەک نەکێشرا. لە ناو یاریبکە بازنە بکێشە.';
        return xs[xs.length - 1] > xs[0] ? null : 'بازنەکە نەجووڵا: x ی دەبێت لە هەر فریمێکدا زیاد بێت (x += ٣).';
      },
