      starter: 'قەبارە(٣٠٠، ٢٨٠)\nگۆڕاو سەبەتە = ١١٠\nگۆڕاو ئ = { x: ١٥٠، y: ٠ }\nگۆڕاو خاڵ = ٠\nیاریبکە(() => {\n  // ١. سەبەتە بجووڵێنە بە کلیل (چەپ/ڕاست) و بە سنوور لە ٠ تا ٢٤٠ بیهێڵەرەوە\n  // ٢. ئ.y += ٤ ؛ کاتێک ئ.y > ٢٤٠: ئەگەر گیرا خاڵ += ١ ؛ ئەستێرەی نوێ\n  پاشبنەمابکە("ئاسمانی")\n  ڕەنگبکە("زەرد")\n  بازنە(ئ.x، ئ.y، ١٠)\n  ڕەنگبکە("نارنجی")\n  لاکێش(سەبەتە، ٢٥٠، ٦٠، ٢٠)\n  ڕەنگبکە("سپی")\n  نووسین("خاڵ: " + خاڵ، ١٠، ٢٥، ٢٠)\n})\n',
