      solution: 'قەبارە(٣٠٠، ٢٨٠)\nگۆڕاو سەبەتە = ١١٠\nگۆڕاو ئ = { x: ١٥٠، y: ٠ }\nگۆڕاو خاڵ = ٠\nیاریبکە(() => {\n  ئەگەر کلیل("چەپ") { سەبەتە -= ٦ }\n  ئەگەر کلیل("ڕاست") { سەبەتە += ٦ }\n  سەبەتە = سنوور(سەبەتە، ٠، ٢٤٠)\n  ئ.y += ٤\n  ئەگەر ئ.y > ٢٤٠ {\n    ئەگەر ئ.x > سەبەتە - ١٠ و ئ.x < سەبەتە + ٧٠ { خاڵ += ١ }\n    ئ = { x: هەڕەمەکی(٢٠، ٢٨٠)، y: ٠ }\n  }\n  پاشبنەمابکە("ئاسمانی")\n  ڕەنگبکە("زەرد")\n  بازنە(ئ.x، ئ.y، ١٠)\n  ڕەنگبکە("نارنجی")\n  لاکێش(سەبەتە، ٢٥٠، ٦٠، ٢٠)\n  ڕەنگبکە("سپی")\n  نووسین("خاڵ: " + خاڵ، ١٠، ٢٥، ٢٠)\n})\n',
