        if (!ys(frames[5]).length) return 'کاتێک بۆشایی دادەگیرێت گوللەیەک دەبێت دروست بێت.';
        const a = Math.min(...ys(frames[5])), b = Math.min(...ys(frames[14]));
        return b < a - 20 ? null : 'گوللەکە دەبێت بەرەو سەرەوە بجووڵێت: گ.y -= ٨ لە هەر فریمێکدا.';
