        if (t(frames[5]) === t(frames[100])) return 'چرکەی ماوە نەگۆڕا: کات -= ١ لە هەر فریمێک.';
        return t(frames[149]).includes('تەواو بوو!') ? null : 'دوای تەواوبوونی کات «تەواو بوو!» نیشان بدە.';
