      recap: ['<code>٦٠ فریم = ١ چرکە</code>، بۆیە <code>٣ * ٦٠</code> = ٣ چرکە.', '<code>ئەگەر کات > ٠ { ... } ئەگەرنا { ... }</code> دوو دۆخی یاری جیا دەکاتەوە.', '<code>خوارکە(کات / ٦٠)</code> چرکەی ماوە نیشان دەدات.'],
