      starter: 'قەبارە(٣٠٠، ١٦٠)\nگۆڕاو بەردەکان = []\nگۆڕاو کات = ٠\nیاریبکە(() => {\n  کات += ١\n  // ئەگەر کات % ٣٠ == ٠ { بەردەکان.زیادبکە({ x: هەڕەمەکی(١٠، ٢٩٠)، y: ٠ }) }\n  پاشبنەمابکە("ڕەش")\n  ڕەنگبکە("خۆڵەمێشی")\n  // بۆ هەر ب لە بەردەکان { ب.y += ٤؛ بازنە(ب.x، ب.y، ٨) }\n  // بەردەکان = بەردەکان.پاڵاوتن(ب => ب.y < ١٦٠)\n})\n',
      hint: 'ئەگەر کات % ٣٠ == ٠ {\n  بەردەکان.زیادبکە({ x: هەڕەمەکی(١٠، ٢٩٠)، y: ٠ })\n}\nبۆ هەر ب لە بەردەکان {\n  ب.y += ٤\n  بازنە(ب.x، ب.y، ٨)\n}\nبەردەکان = بەردەکان.پاڵاوتن(ب => ب.y < ١٦٠)',
      solution: 'قەبارە(٣٠٠، ١٦٠)\nگۆڕاو بەردەکان = []\nگۆڕاو کات = ٠\nیاریبکە(() => {\n  کات += ١\n  ئەگەر کات % ٣٠ == ٠ {\n    بەردەکان.زیادبکە({ x: هەڕەمەکی(١٠، ٢٩٠)، y: ٠ })\n  }\n  پاشبنەمابکە("ڕەش")\n  ڕەنگبکە("خۆڵەمێشی")\n  بۆ هەر ب لە بەردەکان {\n    ب.y += ٤\n    بازنە(ب.x، ب.y، ٨)\n  }\n  بەردەکان = بەردەکان.پاڵاوتن(ب => ب.y < ١٦٠)\n})\n',
      game: true, simulate: [{ n: 200 }],
