      body: `<p>ئەگەر <code>x = ماوسX()</code> بنووسیت، بازنەکە <b>دەپەڕێت</b>. بۆ جووڵەی نەرم، هەر فریمێک تەنها <b>بەشێک</b> لە دووری ماوەکە بڕۆ:</p>
<pre class="ex">x += (ماوسX() - x) * ٠٫١     // ١٠٪ ی دوورییەکە</pre>
<p>هەرچی نزیکتر بیت هەنگاوەکان بچووکتر دەبن، بۆیە دەوەستێت بێ ئەوەی تێپەڕێت. (<code>٠٫١</code> هێواش، <code>٠٫٣</code> خێراتر.)</p>`,
      task: 'بازنەکە نەرم بەدوای ماوسدا بنێرە: <code>x += (ماوسX() - x) * ٠٫١</code> و بە هەمان شێوە <code>y</code>.',
      starter: 'قەبارە(٣٠٠، ١٦٠)\nگۆڕاو x = ٠\nگۆڕاو y = ٠\nیاریبکە(() => {\n  x = ماوسX()؛ y = ماوسY()   // ئەمە دەپەڕێت! بیگۆڕە\n  پاشبنەمابکە("ڕەش")\n  ڕەنگبکە("ئاسمانی")\n  بازنە(x، y، ١٤)\n})\n',
      hint: 'x += (ماوسX() - x) * ٠٫١\ny += (ماوسY() - y) * ٠٫١',
      solution: 'قەبارە(٣٠٠، ١٦٠)\nگۆڕاو x = ٠\nگۆڕاو y = ٠\nیاریبکە(() => {\n  x += (ماوسX() - x) * ٠٫١\n  y += (ماوسY() - y) * ٠٫١\n  پاشبنەمابکە("ڕەش")\n  ڕەنگبکە("ئاسمانی")\n  بازنە(x، y، ١٤)\n})\n',
