      task: 'پێش جووڵەی بەرەو ڕاست، پشکنین بکە: ئەگەر <code>نەخشە[py][px + ١]</code> دیوار (<code>"#"</code>) نییە، <code>px += ١</code>.',
      starter: 'قەبارە(٣٠٠، ٩٠)\nنەگۆڕ نەخشە = ["##########"، "#.....#..#"، "##########"]\nگۆڕاو px = ١\nنەگۆڕ py = ١\nگۆڕاو کات = ٠\nیاریبکە(() => {\n  کات += ١\n  ئەگەر کلیل("ڕاست") و کات % ٦ == ٠ {\n    px += ١   // دیوار نەپشکنراوە! بیگۆڕە\n  }\n  پاشبنەمابکە("ڕەش")\n  بۆ y لە ٠ تا ٢ {\n    بۆ x لە ٠ تا ٩ {\n      ئەگەر نەخشە[y][x] == "#" { ڕەنگبکە("شین")؛ لاکێش(x * ٣٠، y * ٣٠، ٣٠، ٣٠) }\n    }\n  }\n  ڕەنگبکە("زەرد")\n  بازنە(px * ٣٠ + ١٥، py * ٣٠ + ١٥، ١٢)\n})\n',
      hint: 'ئەگەر کلیل("ڕاست") و کات % ٦ == ٠ {\n  ئەگەر نەخشە[py][px + ١] != "#" {\n    px += ١\n  }\n}',
      solution: 'قەبارە(٣٠٠، ٩٠)\nنەگۆڕ نەخشە = ["##########"، "#.....#..#"، "##########"]\nگۆڕاو px = ١\nنەگۆڕ py = ١\nگۆڕاو کات = ٠\nیاریبکە(() => {\n  کات += ١\n  ئەگەر کلیل("ڕاست") و کات % ٦ == ٠ {\n    ئەگەر نەخشە[py][px + ١] != "#" {\n      px += ١\n    }\n  }\n  پاشبنەمابکە("ڕەش")\n  بۆ y لە ٠ تا ٢ {\n    بۆ x لە ٠ تا ٩ {\n      ئەگەر نەخشە[y][x] == "#" { ڕەنگبکە("شین")؛ لاکێش(x * ٣٠، y * ٣٠، ٣٠، ٣٠) }\n    }\n  }\n  ڕەنگبکە("زەرد")\n  بازنە(px * ٣٠ + ١٥، py * ٣٠ + ١٥، ١٢)\n})\n',
