        if (ln(14)[3] - 150 < 30) return 'دوای ١٥ فریم «ڕاست»، هێڵەکە دەبێت بەرەو ڕاست بێت (سینۆس(گۆشە) * ٤٠).';
        if (Math.abs(ln(29)[3] - 150) > 5 || ln(29)[4] > 60) return 'دوای گەڕانەوەی «چەپ»، هێڵەکە دەبێت دووبارە بەرەو سەرەوە بێت.';
