      starter: 'قەبارە(٣٠٠، ١٠٠)\nنەگۆڕ ل = [٠، ٠، ٠، ٠، ٠]\nیاریبکە(() => {\n  ئەگەر کلیککراوە() { ل[خوارکە(ماوسX() / ٦٠)] = ١ }\n  گۆڕاو بردرا = هەڵە\n  // بۆ i لە ٠ تا ٢ { ئەگەر ل[i] == ١ و ل[i + ١] == ١ و ل[i + ٢] == ١ { بردرا = ڕاست } }\n  پاشبنەمابکە("ڕەش")\n  بۆ i لە ٠ تا ٤ {\n    ڕەنگبکە(ل[i] == ١ ? "سەوز" : "خۆڵەمێشی")\n    بازنە(i * ٦٠ + ٣٠، ٥٠، ٢٠)\n  }\n  ڕەنگبکە("سپی")\n  // ئەگەر بردرا { نووسین("بردتەوە! 🎉", ٩٠، ٢٠، ٢٢) }\n})\n',
      hint: 'بۆ i لە ٠ تا ٢ {\n  ئەگەر ل[i] == ١ و ل[i + ١] == ١ و ل[i + ٢] == ١ { بردرا = ڕاست }\n}\n...\nئەگەر بردرا { نووسین("بردتەوە! 🎉", ٩٠، ٢٠، ٢٢) }',
      solution: 'قەبارە(٣٠٠، ١٠٠)\nنەگۆڕ ل = [٠، ٠، ٠، ٠، ٠]\nیاریبکە(() => {\n  ئەگەر کلیککراوە() { ل[خوارکە(ماوسX() / ٦٠)] = ١ }\n  گۆڕاو بردرا = هەڵە\n  بۆ i لە ٠ تا ٢ {\n    ئەگەر ل[i] == ١ و ل[i + ١] == ١ و ل[i + ٢] == ١ { بردرا = ڕاست }\n  }\n  پاشبنەمابکە("ڕەش")\n  بۆ i لە ٠ تا ٤ {\n    ڕەنگبکە(ل[i] == ١ ? "سەوز" : "خۆڵەمێشی")\n    بازنە(i * ٦٠ + ٣٠، ٥٠، ٢٠)\n  }\n  ڕەنگبکە("سپی")\n  ئەگەر بردرا { نووسین("بردتەوە! 🎉", ٩٠، ٢٠، ٢٢) }\n})\n',
